const os = require('os');

function perform(input, context) {
    const total = input.numbers.reduce((sum, number) => sum + number, 0);

    console.log(`Hello ${input.name} from Node ${process.version} on ${os.platform()}/${os.arch()}`);

    return {
        greeting: `Hello, ${input.name}!`,
        total,
        runtime: {node: process.version, platform: os.platform(), arch: os.arch(), hostname: os.hostname()},
        contextAvailable: false,
    };
}

async function perform(input, connection, context) {
    const echo = connection.echo;

    console.log('The token as printed by the script (masked in stdout):', echo.token);

    const response = await fetch(`${echo.baseUri}/get?caller=${encodeURIComponent(input.name)}`, {
        headers: {Authorization: `Bearer ${echo.token}`},
    });
    const body = await response.json();

    return {
        status: response.status,
        tokenAccepted: body.headers.authorization === `Bearer ${echo.token}`,
        echoedQuery: body.args,
        connectionParameterNames: Object.keys(echo).sort(),
    };
}
